fn sorted(j: &J) -> J {
    match j {
        J::Array(x) => {
            let mut v: Vec<String> = x.iter().map(|y| y.to_string()).collect();
            v.sort();
            J::Array(v.into_iter().map(J::String).collect())
        }
        other => other.clone(),
    }
}

fn falsy(j: &J) -> bool {
    match j {
        J::Null => true,
        J::Bool(b) => !b,
        J::String(s) => s.is_empty(),
        J::Array(a) => a.is_empty(),
        J::Object(o) => o.is_empty(),
        J::Number(n) => n.as_f64() == Some(0.0),
    }
}

/// The oracles were recorded with the clock pinned to 2026-11-17 (`RSBOT_TODAY`); without it, run
/// this binary again with it set (setting it in-process would take `unsafe`).
fn pinned_or_rerun(args: &[&str]) -> bool {
    if std::env::var_os("RSBOT_TODAY").is_some() {
        return true;
    }
    let status = std::process::Command::new(std::env::current_exe().expect("own path"))
        .args(args)
        .env("RSBOT_TODAY", "2026-11-17")
        .status()
        .expect("rerun with the clock pinned");
    assert!(status.success(), "the pinned run failed");
    false
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let rest: Vec<&str> = args[1..].iter().map(String::as_str).collect();
    if !pinned_or_rerun(&rest) {
        return;
    }
    let path = &args[1];
    let show: usize = args.iter().position(|x| x == "--show").map(|i| args[i + 1].parse().unwrap()).unwrap_or(0);
    let only: Option<String> = args.iter().position(|x| x == "--fn").map(|i| args[i + 1].clone());
    replay(path, show, only, true);
}

/// Replay a calls file (gzip or plain JSON lines); the totals per column.
fn replay(path: &str, show: usize, only: Option<String>, print: bool) -> [usize; 8] {
    rsbot::data::load();
    std::panic::set_hook(Box::new(|_| {}));
    let file = std::fs::File::open(path).expect("calls file");
    let reader: Box<dyn BufRead> = if path.ends_with(".gz") {
        Box::new(std::io::BufReader::new(flate2::read::GzDecoder::new(file)))
    } else {
        Box::new(std::io::BufReader::new(file))
    };
    // fn -> [same, falsy-same, differ, unported, panicked, raised-in-python, unknown, memory differs]
    let mut tally: BTreeMap<String, [usize; 8]> = BTreeMap::new();
    let mut shown: BTreeMap<String, usize> = BTreeMap::new();
    // The UNPORTED panics by message: the dependencies in other files that block a check.
    let mut blockers: BTreeMap<String, usize> = BTreeMap::new();
    for line in reader.lines() {
        let rec: J = serde_json::from_str(&line.unwrap()).unwrap();
        let name = rec["fn"].as_str().unwrap().to_string();
        if let Some(o) = &only {
            if *o != name {
                continue;
            }
        }
        let t = tally.entry(name.clone()).or_insert([0; 8]);
        if !rec["raised"].is_null() {
            t[5] += 1;
            continue;
        }
        let a: Vec<J> = rec["args"].as_array().cloned().unwrap_or_default();
        let before = &rec["memory"];
        let none = before.is_array() && before[1].is_null();
        let mem = match before.get(1).and_then(|m| m.as_object()) {
            Some(m) => Memory::from_plain(m),
            None => Memory::new(),
        };
        let got = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| call(&name, &a, mem, none)));
        let (res, mem_after) = match got {
            Ok(Some(((j, set), m))) => ((j, set), m),
            Ok(None) => {
                t[6] += 1;
                continue;
            }
            Err(e) => {
                let msg = e.downcast_ref::<String>().cloned().or_else(|| e.downcast_ref::<&str>().map(|s| s.to_string())).unwrap_or_default();
                if msg.starts_with("UNPORTED") {
                    t[3] += 1;
                    *blockers.entry(msg).or_insert(0) += 1;
                } else {
                    t[4] += 1;
                    let k = shown.entry(name.clone()).or_insert(0);
                    if *k < show {
                        *k += 1;
                        println!("PANIC {name} {msg}\n  args {}", serde_json::to_string(&a).unwrap());
                    }
                }
                continue;
            }
        };
        let (j, set) = res;
        let want = &rec["result"];
        let same = if set { sorted(&j) == sorted(want) } else { j == *want };
        if same {
            t[0] += 1;
        } else if falsy(&j) && falsy(want) {
            t[1] += 1;
        } else {
            t[2] += 1;
            let k = shown.entry(name.clone()).or_insert(0);
            if *k < show {
                *k += 1;
                println!("DIFF {name}\n  args {}\n  want {}\n  got  {}", serde_json::to_string(&a).unwrap(), want, j);
            }
            continue;
        }
        // The memory the call left behind, key by key (understood and turns aside).
        if let Some(after) = rec["after"].as_object() {
            let mine = mem_after.to_plain();
            let differs = after.iter().any(|(k, x)| mine.get(k) != Some(x))
                || mine.keys().any(|k| !after.contains_key(k) && !["understood", "turns", "intent_wants", "asked_now"].contains(&k.as_str()));
            if differs {
                t[7] += 1;
                let k = shown.entry(name.clone()).or_insert(0);
                if *k < show {
                    *k += 1;
                    println!("MEMORY {name}\n  args {}", serde_json::to_string(&a).unwrap());
                }
            }
        }
    }
    let mut total = [0usize; 8];
    for t in tally.values() {
        for i in 0..8 {
            total[i] += t[i];
        }
    }
    if !print {
        return total;
    }
    println!("{:<44} {:>6} {:>6} {:>6} {:>8} {:>6} {:>6} {:>6} {:>6}", "function", "same", "falsy", "DIFF", "unported", "PANIC", "pyraise", "skip", "MEMDIF");
    for (name, t) in &tally {
        println!("{:<44} {:>6} {:>6} {:>6} {:>8} {:>6} {:>6} {:>6} {:>6}", name, t[0], t[1], t[2], t[3], t[4], t[5], t[6], t[7]);
    }
    let mut by_count: Vec<_> = blockers.iter().collect();
    by_count.sort_by(|a, b| b.1.cmp(a.1));
    for (msg, n) in by_count.iter().take(12) {
        println!("blocked {n:>5}  {}", msg.lines().next().unwrap_or(""));
    }
    println!("{:<44} {:>6} {:>6} {:>6} {:>8} {:>6} {:>6} {:>6} {:>6}", "TOTAL", total[0], total[1], total[2], total[3], total[4], total[5], total[6], total[7]);
    total
}

#[cfg(test)]
mod tests {
    /// The cases in harness/mem1_expect.jsonl, with PyBot's own results (branches the corpus
    /// does not reach among them): none may differ or panic; an UNPORTED dependency is skipped.
    #[test]
    fn python_expectations() {
        if !super::pinned_or_rerun(&["tests::python_expectations", "--exact", "--nocapture"]) {
            return;
        }
        let path = concat!(env!("CARGO_MANIFEST_DIR"), "/harness/mem1_expect.jsonl");
        let t = super::replay(path, 5, None, true);
        assert_eq!(t[2], 0, "results that differ from PyBot");
        assert_eq!(t[4], 0, "panics other than UNPORTED");
        assert_eq!(t[7], 0, "memory that differs from PyBot");
    }
}
